// Client list import, v3: compares a client list sheet with Emails Beta by EMAIL,
// picks the next batch of new contacts for the mailbox check, and (in append
// mode) groups checked contacts by evidence and plans the Emails Beta rows.
//
// Every run does both:
//   * picks the next `batchSize` new contacts that have no "Mailbox check" yet (the
//     nodes after this one search all 7 mailboxes for them and save the result), and
//   * groups the contacts that are already checked by evidence and plans the Emails
//     Beta rows for every group whose members are all checked.
// The single switch `addToEmailsBeta` decides whether those rows are appended
// (true) or only shown as a preview (false).
//
// Rules:
//  * An address already in an Emails Beta Email cell => existing client. Never
//    changed (name, emails, folder).
//  * Any other address => new contact. (One Emails Beta row per group; no extra name-only rows.) Contacts are only put in one group when
//    the mailbox check SAW them together: contact B appears (From/To/Cc) on
//    messages found for contact A, directly or through a chain. The list's
//    account Name is NOT used for grouping; it only names the group (first
//    contact's account Name). A contact linked to an existing client is flagged,
//    never merged into it.
//  * A group is only appended when every member has been checked. No
//    conversation found in any mailbox => still appended, flagged in Batch, with
//    a blank Platform so the intake workflow skips it.
//  * Platform is written as one entry per email (JSON array), because the intake
//    workflow assigns platforms to emails by position.
//  * The intake workflow finds a client's Drive folder by Name only, so a new
//    group whose name equals an existing Emails Beta Name is renamed
//    "Name (address prefix)".
//  * Matching is by exact address only, never by name.
const cfg = $('Set Config').first().json;
const batchSize = Math.max(1, Number(cfg.batchSize) || 10);
const batch = String(cfg.batchLabel || '');
const noConvFlag = String(cfg.noConversationFlag || 'no conversation found');
const listOf = (v) => String(v || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const ownDomains = listOf(cfg.ownDomains), ownAddrs = new Set(listOf(cfg.ownAddresses)), ownContains = listOf(cfg.ownContains);
const isOwn = (a) => ownAddrs.has(a) || ownDomains.some(d => a.endsWith('@' + d)) || ownContains.some(s => a.includes(s));

const SRC = { name: 'Name', email: 'Contact email', contact: 'Contact name', status: 'Status', matched: 'Matched client', check: 'Mailbox check', boxes: 'Mailboxes', linked: 'Linked contacts' };
const BETA = { name: 'Name', email: 'Email', processed: 'Processed', platform: 'Platform', synced: 'last_synced_at', batch: 'Batch' };

// On the second pass (after this run's check results were saved) the list is read again, so
// groups completed during this run are planned in the same run.
const reread = (() => { try { return $('📥 Re-read Source List').isExecuted === true; } catch (e) { return false; } })();
const srcItems = $(reread ? '📥 Re-read Source List' : '📥 Read Source List').all().map(i => i.json);
const betaItems = $('📥 Read Emails Beta').all().map(i => i.json);
const srcHeader = (($('📥 Read List Header').first().json.values || [])[0]) || [];
if (srcItems.length === 0) throw new Error('List sheet has no data rows');

const keyOf = (obj, wanted, label) => {
  const k = Object.keys(obj).find(x => x.trim().toLowerCase() === wanted.toLowerCase());
  if (!k) throw new Error(`${label}: column "${wanted}" not found (columns: ${Object.keys(obj).join(' | ')})`);
  return k;
};
const colLetter = (i) => { let s = ''; i += 1; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
// Output columns (Status, Matched client, Mailbox check, Mailboxes, Linked contacts): found by
// header name; any that is missing is added to the right of the last header automatically.
const headerIdx = (wanted) => srcHeader.findIndex(h => String(h || '').trim().toLowerCase() === wanted.toLowerCase());
let nextFree = srcHeader.length;
const headersToAdd = [];
const outCol = (wanted) => {
  let i = headerIdx(wanted);
  if (i < 0) { i = nextFree++; headersToAdd.push({ index: i, name: wanted }); }
  return i;
};
const str = (v) => String(v ?? '').trim();
const addrsOf = (v) => String(v || '').split(/[,;\s]+/).map(e => e.trim().toLowerCase()).filter(Boolean);

// ---- Emails Beta ----
const bk = {};
for (const [f, h] of Object.entries(BETA)) bk[f] = keyOf(betaItems[0] || {}, h, 'Emails Beta');
const betaByEmail = new Map();
const takenNames = new Set();
for (const row of betaItems) {
  const nm = str(row[bk.name]);
  if (nm) takenNames.add(nm.toLowerCase());
  for (const a of addrsOf(str(row[bk.email]))) if (!betaByEmail.has(a)) betaByEmail.set(a, { name: nm, batch: str(row[bk.batch]) });
}

// ---- list sheet ----
const sk = {};
for (const f of ['name', 'email', 'contact']) sk[f] = keyOf(srcItems[0], SRC[f], 'List sheet');
// check columns may not exist yet (added below): read them only when present
for (const f of ['check', 'boxes', 'linked']) sk[f] = Object.keys(srcItems[0]).find(x => x.trim().toLowerCase() === SRC[f].toLowerCase()) || null;
const col = { status: colLetter(outCol(SRC.status)), matched: colLetter(outCol(SRC.matched)), check: colLetter(outCol(SRC.check)), boxes: colLetter(outCol(SRC.boxes)), linked: colLetter(outCol(SRC.linked)) };
const lastRow = Math.max(...srcItems.map(r => Number(r.row_number) || 0));
if (!(lastRow >= 2)) throw new Error('List sheet rows have no row_number');
const n = lastRow - 1;
const out = Array.from({ length: n }, () => ({ status: '', matched: '' }));
const stats = { existing: 0, existingWithNewAddress: 0, newContacts: 0, noEmail: 0, duplicateInList: 0 };
const existingWithNewAddress = [];
const seen = new Map(); const dups = [];
const contacts = [];

for (const row of srcItems) {
  const r = Number(row.row_number) - 2;
  const addrs = addrsOf(str(row[sk.email]));
  if (addrs.length === 0) { out[r].status = 'No email'; stats.noEmail++; continue; }
  if (addrs.every(a => seen.has(a))) { out[r].status = 'Duplicate in list'; dups.push({ r, of: seen.get(addrs[0]) }); stats.duplicateInList++; continue; }
  addrs.forEach(a => { if (!seen.has(a)) seen.set(a, r); });
  const hit = addrs.map(a => betaByEmail.get(a)).filter(Boolean);
  if (hit.length) {
    const first = hit[0];
    const missing = addrs.filter(a => !betaByEmail.has(a));
    out[r].matched = first.name;
    out[r].status = first.batch ? `New (${first.batch})` : 'Existing';
    if (missing.length) { out[r].status += ` (+${missing.length} address not in Emails Beta)`; stats.existingWithNewAddress++; existingWithNewAddress.push({ row: r + 2, client: first.name, addresses: missing }); }
    stats.existing++;
    continue;
  }
  const check = sk.check ? str(row[sk.check]) : '';
  const boxes = sk.boxes ? str(row[sk.boxes]) : '';
  contacts.push({
    r, row: r + 2, account: str(row[sk.name]), addrs, contactName: str(row[sk.contact]),
    check, checked: /^(found|not found)$/i.test(check), found: /^found$/i.test(check),
    types: [...new Set((boxes.match(/outlook|gmail/gi) || []).map(t => t.toLowerCase()))],
    boxes, linked: sk.linked ? addrsOf(str(row[sk.linked])).filter(a => !isOwn(a)) : []   // own addresses saved by an earlier run are ignored
  });
  stats.newContacts++;
}

const addrToContact = new Map();
contacts.forEach((c, i) => c.addrs.forEach(a => addrToContact.set(a, i)));

// ---- evidence grouping (union-find over contacts the check saw together) ----
const parent = contacts.map((_, i) => i);
const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); };
const existingLink = new Map();   // contact index -> Set of existing client names
// An address that shows up in the linked lists of many different contacts is almost certainly
// one of our own mailboxes or a mass sender, not a person who belongs to a client. Using it
// would chain unrelated clients into one group, so it is ignored for grouping and reported.
const hubThreshold = Math.max(3, Number(cfg.hubThreshold) || 4);
const linkCount = new Map();
contacts.forEach(c => new Set(c.linked).forEach(a => linkCount.set(a, (linkCount.get(a) || 0) + 1)));
const hubs = new Set([...linkCount].filter(([, k]) => k >= hubThreshold).map(([a]) => a));
contacts.forEach((c, i) => {
  for (const a of c.linked) {
    if (hubs.has(a)) continue;
    if (addrToContact.has(a)) union(i, addrToContact.get(a));
    else if (betaByEmail.has(a)) { if (!existingLink.has(i)) existingLink.set(i, new Set()); existingLink.get(i).add(betaByEmail.get(a).name); }
  }
});
const groupsMap = new Map();
contacts.forEach((c, i) => { const root = find(i); if (!groupsMap.has(root)) groupsMap.set(root, []); groupsMap.get(root).push(i); });
const groups = [...groupsMap.values()].map(ix => ix.sort((a, b) => a - b));

const uniqueName = (base, firstAddr) => {
  let name = base || firstAddr.split('@')[0];
  if (!takenNames.has(name.toLowerCase())) { takenNames.add(name.toLowerCase()); return name; }
  const local = firstAddr.split('@')[0];
  let cand = `${name} (${local})`, k = 2;
  while (takenNames.has(cand.toLowerCase())) cand = `${name} (${local}) ${k++}`;
  takenNames.add(cand.toLowerCase());
  return cand;
};
const platformValue = (allAddrs, group) => {
  const union = [...new Set(group.flatMap(i => contacts[i].types))];
  if (union.length === 0) return '';
  const per = allAddrs.map(a => { const t = contacts[addrToContact.get(a)].types; const use = t.length ? t : union; return use.length === 1 ? use[0] : use; });
  return per.length === 1 && typeof per[0] === 'string' ? per[0] : JSON.stringify(per);
};

const appendRows = [];
const pendingGroups = [];
const nameClashes = [];
const sameAccountNote = [];
const bigGroups = [];
const noConversation = [];
const toCheck = [];
const newStatus = (c, i) => {
  let s = !c.checked ? 'New (not checked yet)' : (c.found ? 'New (conversation found)' : `New (${noConvFlag})`);
  if (existingLink.has(i)) s += `; linked to existing client ${[...existingLink.get(i)].join(' / ')}`;
  return s;
};
contacts.forEach((c, i) => { out[c.r].status = newStatus(c, i); });

for (const c of contacts) { if (!c.checked && toCheck.length < batchSize) toCheck.push({ row: c.row, addrs: c.addrs }); }
for (const g of groups) {
  if (!g.every(i => contacts[i].checked)) { pendingGroups.push(g.map(i => contacts[i].row)); continue; }
  if (g.length > 6) bigGroups.push({ rows: g.map(i => contacts[i].row), size: g.length });
  const first = contacts[g[0]];
  const base = first.account || first.contactName || '';
  const name = uniqueName(base, first.addrs[0]);
  if (name.toLowerCase() !== (base || first.addrs[0].split('@')[0]).toLowerCase()) nameClashes.push({ row: first.row, original: base, assigned: name });
  const allAddrs = [...new Set(g.flatMap(i => contacts[i].addrs))];
  const found = g.some(i => contacts[i].found);
  const mk = (nm, email, platform, label) => ({ [bk.name]: nm, [bk.email]: email, [bk.processed]: 'FALSE', [bk.platform]: platform, [bk.synced]: '', [bk.batch]: label });
  const label = found ? batch : `${batch} - ${noConvFlag}`;
  appendRows.push(mk(name, allAddrs.join(', '), found ? platformValue(allAddrs, g) : '', label));
  if (!found) noConversation.push({ name, rows: g.map(i => contacts[i].row) });
  g.forEach(i => {
    const c = contacts[i];
    out[c.r].matched = name;
    // (no name-only rows for the other contacts: who belongs to a group is in the list sheet's Matched client column)
  });
  g.forEach(i => { if (existingLink.has(i)) sameAccountNote.push({ row: contacts[i].row, newClient: name, linkedToExisting: [...existingLink.get(i)] }); });
}
// With the switch on, every group whose members are all checked is added in this run.
const addOn = cfg.addToEmailsBeta === true || String(cfg.addToEmailsBeta).toLowerCase() === 'true';
const rowsToAdd = addOn ? appendRows : [];
for (const d of dups) out[d.r].matched = out[d.of].matched;

const q = (t) => `'${String(t).replace(/'/g, "''")}'`;
const srcTab = String(cfg.sourceTab);
const sid = encodeURIComponent(cfg.sourceSheetId);
const sourceUpdate = {
  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values:batchUpdate`,
  body: { valueInputOption: 'RAW', data: [
    ...headersToAdd.map(h => ({ range: `${q(srcTab)}!${colLetter(h.index)}1`, values: [[h.name]] })),
    { range: `${q(srcTab)}!${col.status}2:${col.status}${n + 1}`, values: out.map(o => [o.status]) },
    { range: `${q(srcTab)}!${col.matched}2:${col.matched}${n + 1}`, values: out.map(o => [o.matched]) }
  ] }
};

return [{ json: {
  addToEmailsBeta: addOn, rowsToAdd,
  summary: {
    listRows: srcItems.length, ...stats,
    checked: contacts.filter(c => c.checked).length,
    conversationFound: contacts.filter(c => c.found).length,
    notChecked: contacts.filter(c => !c.checked).length,
    nextBatch: toCheck.length,
    groupsReady: groups.length - pendingGroups.length,
    groupsPending: pendingGroups.length,
    rowsToAppendToEmailsBeta: appendRows.length,
    noConversationClients: noConversation.length,
    nameClashesRenamed: nameClashes.length,
    largeGroups: bigGroups.length,
    hubAddressesIgnored: hubs.size
  },
  headersAdded: headersToAdd.map(h => h.name),
  toCheck, columns: col, srcTab, sourceSheetId: cfg.sourceSheetId,
  hubAddressesIgnored: [...hubs],
  nameClashes, linkedToExisting: sameAccountNote, bigGroups, noConversation, existingWithNewAddress,
  preview: appendRows.slice(0, 30).map(r => ({ Name: r[bk.name], Email: r[bk.email], Platform: r[bk.platform], Batch: r[bk.batch] })),
  sourceUpdate, appendRows
} }];

// One item per contact of the current batch, with the ready-made search URLs the
// mailbox nodes use (so the nodes only need one simple expression).
const c = $('🧮 Compare & Plan').first().json;
const enc = encodeURIComponent;
return c.toCheck.map((t, ci) => {
  const gq = t.addrs.map(a => `from:${a} OR to:${a} OR cc:${a}`).join(' OR ');
  return { json: {
    ci, row: t.row, addrs: t.addrs,
    outlookUrl: 'https://graph.microsoft.com/v1.0/me/messages?$top=10&$select=from,toRecipients,ccRecipients,sentDateTime&$search=' + enc('"' + t.addrs.join(' OR ') + '"'),
    gmailListUrl: 'https://gmail.googleapis.com/gmail/v1/users/me/threads?maxResults=5&q=' + enc(gq)
  } };
});

// Turns each contact's thread list (one response per contact, same order) into
// one item per thread to fetch (headers only). A placeholder item keeps the
// chain alive when there are no threads at all.
const lists = $input.all();
const out = [];
lists.forEach((it, ci) => {
  const threads = (it.json && it.json.threads) || [];
  for (const t of threads.slice(0, 5)) {
    out.push({ json: { ci, url: `https://gmail.googleapis.com/gmail/v1/users/me/threads/${t.id}?format=metadata&metadataHeaders=From&metadataHeaders=To&metadataHeaders=Cc` } });
  }
});
if (out.length === 0) out.push({ json: { ci: -1, url: 'https://gmail.googleapis.com/gmail/v1/users/me/profile' } });
return out;

// Back to one item per contact: the headers of every message in the fetched
// threads, plus an error flag if the list call or any thread call failed.
const EXPAND = '📬 Expand Threads (Emily)';
const LIST = '📬 List Threads (Emily)';
const contacts = $('🔎 Contacts to Check').all();
const lists = $(LIST).all();
const exp = $(EXPAND).all();
const threads = $input.all();
const errText = (e) => { try { return String(typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 240); } catch (x) { return 'error'; } };
const res = contacts.map((_, ci) => {
  const e = lists[ci] && lists[ci].json && lists[ci].json.error;
  return { error: !!e, errorMessage: e ? 'list: ' + errText(e) : '', messages: [] };
});
exp.forEach((e, k) => {
  const ci = e.json.ci;
  if (ci < 0 || !res[ci]) return;
  const t = threads[k] && threads[k].json;
  if (!t || t.error) { res[ci].error = true; res[ci].errorMessage = res[ci].errorMessage || ('thread: ' + (t ? errText(t.error) : 'no response')); return; }
  for (const m of (t.messages || [])) {
    const h = {};
    for (const x of (m.payload && m.payload.headers) || []) h[String(x.name).toLowerCase()] = x.value;
    res[ci].messages.push({ from: h.from || '', to: h.to || '', cc: h.cc || '' });
  }
});
return res.map((r, ci) => ({ json: { ci, ...r } }));

// Turns each contact's thread list (one response per contact, same order) into
// one item per thread to fetch (headers only). A placeholder item keeps the
// chain alive when there are no threads at all.
const lists = $input.all();
const out = [];
lists.forEach((it, ci) => {
  const threads = (it.json && it.json.threads) || [];
  for (const t of threads.slice(0, 5)) {
    out.push({ json: { ci, url: `https://gmail.googleapis.com/gmail/v1/users/me/threads/${t.id}?format=metadata&metadataHeaders=From&metadataHeaders=To&metadataHeaders=Cc` } });
  }
});
if (out.length === 0) out.push({ json: { ci: -1, url: 'https://gmail.googleapis.com/gmail/v1/users/me/profile' } });
return out;

// Back to one item per contact: the headers of every message in the fetched
// threads, plus an error flag if the list call or any thread call failed.
const EXPAND = '📬 Expand Threads (Terry)';
const LIST = '📬 List Threads (Terry)';
const contacts = $('🔎 Contacts to Check').all();
const lists = $(LIST).all();
const exp = $(EXPAND).all();
const threads = $input.all();
const errText = (e) => { try { return String(typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 240); } catch (x) { return 'error'; } };
const res = contacts.map((_, ci) => {
  const e = lists[ci] && lists[ci].json && lists[ci].json.error;
  return { error: !!e, errorMessage: e ? 'list: ' + errText(e) : '', messages: [] };
});
exp.forEach((e, k) => {
  const ci = e.json.ci;
  if (ci < 0 || !res[ci]) return;
  const t = threads[k] && threads[k].json;
  if (!t || t.error) { res[ci].error = true; res[ci].errorMessage = res[ci].errorMessage || ('thread: ' + (t ? errText(t.error) : 'no response')); return; }
  for (const m of (t.messages || [])) {
    const h = {};
    for (const x of (m.payload && m.payload.headers) || []) h[String(x.name).toLowerCase()] = x.value;
    res[ci].messages.push({ from: h.from || '', to: h.to || '', cc: h.cc || '' });
  }
});
return res.map((r, ci) => ({ json: { ci, ...r } }));

// Turns each contact's thread list (one response per contact, same order) into
// one item per thread to fetch (headers only). A placeholder item keeps the
// chain alive when there are no threads at all.
const lists = $input.all();
const out = [];
lists.forEach((it, ci) => {
  const threads = (it.json && it.json.threads) || [];
  for (const t of threads.slice(0, 5)) {
    out.push({ json: { ci, url: `https://gmail.googleapis.com/gmail/v1/users/me/threads/${t.id}?format=metadata&metadataHeaders=From&metadataHeaders=To&metadataHeaders=Cc` } });
  }
});
if (out.length === 0) out.push({ json: { ci: -1, url: 'https://gmail.googleapis.com/gmail/v1/users/me/profile' } });
return out;

// Back to one item per contact: the headers of every message in the fetched
// threads, plus an error flag if the list call or any thread call failed.
const EXPAND = '📬 Expand Threads (Office)';
const LIST = '📬 List Threads (Office)';
const contacts = $('🔎 Contacts to Check').all();
const lists = $(LIST).all();
const exp = $(EXPAND).all();
const threads = $input.all();
const errText = (e) => { try { return String(typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 240); } catch (x) { return 'error'; } };
const res = contacts.map((_, ci) => {
  const e = lists[ci] && lists[ci].json && lists[ci].json.error;
  return { error: !!e, errorMessage: e ? 'list: ' + errText(e) : '', messages: [] };
});
exp.forEach((e, k) => {
  const ci = e.json.ci;
  if (ci < 0 || !res[ci]) return;
  const t = threads[k] && threads[k].json;
  if (!t || t.error) { res[ci].error = true; res[ci].errorMessage = res[ci].errorMessage || ('thread: ' + (t ? errText(t.error) : 'no response')); return; }
  for (const m of (t.messages || [])) {
    const h = {};
    for (const x of (m.payload && m.payload.headers) || []) h[String(x.name).toLowerCase()] = x.value;
    res[ci].messages.push({ from: h.from || '', to: h.to || '', cc: h.cc || '' });
  }
});
return res.map((r, ci) => ({ json: { ci, ...r } }));

// Combines the 7 mailbox searches per contact: is there a conversation, in which
// mailboxes, and who else appears on those messages. Contacts where any mailbox
// call failed are left unchecked (retried next run) -- "not found" is only
// written when every mailbox answered.
const cfg = $('Set Config').first().json;
const contacts = $('🔎 Contacts to Check').all().map(i => i.json);
const maxP = Math.max(1, Number(cfg.maxParticipants) || 8);
const ownDomains = String(cfg.ownDomains || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const ownAddrs = new Set(String(cfg.ownAddresses || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean));
const ownContains = String(cfg.ownContains || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const isOwn = (a) => ownAddrs.has(a) || ownDomains.some(d => a.endsWith('@' + d)) || ownContains.some(s => a.includes(s));
const ADDR = /[A-Za-z0-9._%+'-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const pick = (s) => (String(s || '').match(ADDR) || []).map(x => x.toLowerCase());

const OUTLOOK = [['Outlook-Jack', '📥 Outlook (Jack)'], ['Outlook-Mia', '📥 Outlook (Mia)'], ['Outlook-Eve', '📥 Outlook (Eve)'], ['Outlook-Yolanda', '📥 Outlook (Yolanda)']];
const GMAIL = [['Gmail-Emily', '📬 Collect Gmail (Emily)'], ['Gmail-Terry', '📬 Collect Gmail (Terry)'], ['Gmail-Office', '📬 Collect Gmail (Office)']];

const perContact = contacts.map(() => ({ error: false, errors: [], boxes: [], participants: new Set(), msgs: [] }));
const errText = (e) => { try { return String(typeof e === 'string' ? e : (e.message || JSON.stringify(e))).slice(0, 240); } catch (x) { return 'error'; } };
const addMessages = (ci, label, msgs) => {
  const own = contacts[ci].addrs;
  let hit = false;
  for (const m of msgs) {
    const people = [...new Set(m)];
    if (!people.some(a => own.includes(a))) continue;      // search hit that does not involve the contact
    hit = true;
    const others = people.filter(a => !isOwn(a));
    if (others.length <= maxP) others.forEach(a => { if (!own.includes(a)) perContact[ci].participants.add(a); });
  }
  if (hit) perContact[ci].boxes.push(label);
};
// Which mailbox did each Outlook node really search? Graph names the user in @odata.context.
const mailboxIds = {};
for (const [label, node] of OUTLOOK) {
  const items = $(node).all();
  for (const it of items) {
    const m = /users\('([^']+)'\)/.exec(String((it.json && it.json['@odata.context']) || ''));
    if (m) { mailboxIds[label] = m[1]; break; }
  }
}
const sameBox = {};
for (const [label, id] of Object.entries(mailboxIds)) (sameBox[id] = sameBox[id] || []).push(label);
const warnings = Object.values(sameBox).filter(l => l.length > 1).map(l => `${l.join(' and ')} searched the SAME mailbox -- check the credential on those nodes. Nothing was saved.`);

for (const [label, node] of OUTLOOK) {
  const items = $(node).all();
  contacts.forEach((_, ci) => {
    const j = items[ci] && items[ci].json;
    if (!j || j.error || !Array.isArray(j.value)) { perContact[ci].error = true; perContact[ci].errors.push(`${label}: ${j && j.error ? errText(j.error) : 'no usable response'}`); return; }
    addMessages(ci, label, j.value.map(m => [
      ...pick(m.from && m.from.emailAddress && m.from.emailAddress.address),
      ...(m.toRecipients || []).flatMap(r => pick(r.emailAddress && r.emailAddress.address)),
      ...(m.ccRecipients || []).flatMap(r => pick(r.emailAddress && r.emailAddress.address))
    ]));
  });
}
for (const [label, node] of GMAIL) {
  const items = $(node).all();
  contacts.forEach((_, ci) => {
    const j = items[ci] && items[ci].json;
    if (!j || j.error) { perContact[ci].error = true; perContact[ci].errors.push(`${label}: ${(j && j.errorMessage) || 'no response'}`); return; }
    addMessages(ci, label, (j.messages || []).map(m => [...pick(m.from), ...pick(m.to), ...pick(m.cc)]));
  });
}

const tab = String(cfg.sourceTab);
const col = $('🧮 Compare & Plan').first().json.columns;
const q = (t) => `'${String(t).replace(/'/g, "''")}'`;
const data = [];
const done = [];
const retry = [];
const retryDetails = [];
contacts.forEach((c, ci) => {
  const r = perContact[ci];
  if (warnings.length || r.error) { retry.push(c.row); if (r.errors.length) retryDetails.push({ row: c.row, errors: r.errors }); return; }
  const found = r.boxes.length > 0;
  const vals = { check: found ? 'Found' : 'Not found', boxes: r.boxes.join('; '), linked: [...r.participants].join(', ') };
  for (const f of ['check', 'boxes', 'linked']) data.push({ range: `${q(tab)}!${col[f]}${c.row}`, values: [[vals[f]]] });
  // Status now, so it does not wait for the next run to catch up with the check columns.
  data.push({ range: `${q(tab)}!${col.status}${c.row}`, values: [[found ? 'New (conversation found)' : `New (${String(cfg.noConversationFlag || 'no conversation found')})`]] });
  done.push({ row: c.row, result: found ? 'Found' : 'Not found', mailboxes: r.boxes, linked: [...r.participants] });
});
return [{ json: {
  hasWrites: data.length > 0,
  checkedThisRun: done, retryNextRun: retry, retryDetails, mailboxIds, warnings,
  update: { url: `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(cfg.sourceSheetId)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data } }
} }];

const c0 = $('🧮 Compare & Plan').first().json;      // plan at the START of the run
const ran = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const c = ran('🧮 Plan Again') ? $('🧮 Plan Again').first().json : c0;   // plan after this run's check results
const agg = ran('🧩 Aggregate Check Results') ? $('🧩 Aggregate Check Results').first().json : null;
const appended = ran('➕ Append New Clients to Emails Beta');
const parts = [];
parts.push(agg ? `checked ${agg.checkedThisRun.length} contact(s) in the mailboxes` : (c0.toCheck.length ? 'no results saved (see warnings / retry details)' : 'nothing left to check'));
parts.push(appended ? `ADDED ${c.rowsToAdd.length} row(s) to Emails Beta` : (c.addToEmailsBeta ? 'nothing new to add yet (groups are added as soon as all their members are checked)' : `PREVIEW only (addToEmailsBeta = false): ${c.appendRows.length} row(s) would be added`));
return [{ json: {
  result: parts.join(' | '),
  afterThisRun: {
    contactsChecked: c.summary.checked,
    contactsNotChecked: c.summary.notChecked,
    savedThisRun: agg ? agg.checkedThisRun.length : 0,
    failedAndRetriedNextRun: agg ? agg.retryNextRun.length : 0,
    groupsReady: c.summary.groupsReady,
    groupsPending: c.summary.groupsPending,
    rowsPlanned: c.appendRows.length
  },
  startOfRun: c0.summary,
  checkedThisRun: agg ? agg.checkedThisRun : undefined,
  retryNextRun: agg ? agg.retryNextRun : undefined,
  retryDetails: agg ? agg.retryDetails : undefined,
  warnings: agg ? agg.warnings : undefined,
  mailboxIds: agg ? agg.mailboxIds : undefined,
  noConversation: c.noConversation, linkedToExisting: c.linkedToExisting, largeGroups: c.bigGroups,
  nameClashes: c.nameClashes, hubAddressesIgnored: c.hubAddressesIgnored, existingWithNewAddress: c.existingWithNewAddress, preview: c.preview
} }];

// Client list import, v3: compares a client list sheet with Emails Beta by EMAIL,
// picks the next batch of new contacts for the mailbox check, and (in append
// mode) groups checked contacts by evidence and plans the Emails Beta rows.
//
// Every run does both:
//   * picks the next `batchSize` new contacts that have no "Mailbox check" yet (the
//     nodes after this one search all 7 mailboxes for them and save the result), and
//   * groups the contacts that are already checked by evidence and plans the Emails
//     Beta rows for every group whose members are all checked.
// The single switch `addToEmailsBeta` decides whether those rows are appended
// (true) or only shown as a preview (false).
//
// Rules:
//  * An address already in an Emails Beta Email cell => existing client. Never
//    changed (name, emails, folder).
//  * Any other address => new contact. (One Emails Beta row per group; no extra name-only rows.) Contacts are only put in one group when
//    the mailbox check SAW them together: contact B appears (From/To/Cc) on
//    messages found for contact A, directly or through a chain. The list's
//    account Name is NOT used for grouping; it only names the group (first
//    contact's account Name). A contact linked to an existing client is flagged,
//    never merged into it.
//  * A group is only appended when every member has been checked. No
//    conversation found in any mailbox => still appended, flagged in Batch, with
//    a blank Platform so the intake workflow skips it.
//  * Platform is written as one entry per email (JSON array), because the intake
//    workflow assigns platforms to emails by position.
//  * The intake workflow finds a client's Drive folder by Name only, so a new
//    group whose name equals an existing Emails Beta Name is renamed
//    "Name (address prefix)".
//  * Matching is by exact address only, never by name.
const cfg = $('Set Config').first().json;
const batchSize = Math.max(1, Number(cfg.batchSize) || 10);
const batch = String(cfg.batchLabel || '');
const noConvFlag = String(cfg.noConversationFlag || 'no conversation found');
const listOf = (v) => String(v || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const ownDomains = listOf(cfg.ownDomains), ownAddrs = new Set(listOf(cfg.ownAddresses)), ownContains = listOf(cfg.ownContains);
const isOwn = (a) => ownAddrs.has(a) || ownDomains.some(d => a.endsWith('@' + d)) || ownContains.some(s => a.includes(s));

const SRC = { name: 'Name', email: 'Contact email', contact: 'Contact name', status: 'Status', matched: 'Matched client', check: 'Mailbox check', boxes: 'Mailboxes', linked: 'Linked contacts' };
const BETA = { name: 'Name', email: 'Email', processed: 'Processed', platform: 'Platform', synced: 'last_synced_at', batch: 'Batch' };

// On the second pass (after this run's check results were saved) the list is read again, so
// groups completed during this run are planned in the same run.
const reread = (() => { try { return $('📥 Re-read Source List').isExecuted === true; } catch (e) { return false; } })();
const srcItems = $(reread ? '📥 Re-read Source List' : '📥 Read Source List').all().map(i => i.json);
const betaItems = $('📥 Read Emails Beta').all().map(i => i.json);
const srcHeader = (($('📥 Read List Header').first().json.values || [])[0]) || [];
if (srcItems.length === 0) throw new Error('List sheet has no data rows');

const keyOf = (obj, wanted, label) => {
  const k = Object.keys(obj).find(x => x.trim().toLowerCase() === wanted.toLowerCase());
  if (!k) throw new Error(`${label}: column "${wanted}" not found (columns: ${Object.keys(obj).join(' | ')})`);
  return k;
};
const colLetter = (i) => { let s = ''; i += 1; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
// Output columns (Status, Matched client, Mailbox check, Mailboxes, Linked contacts): found by
// header name; any that is missing is added to the right of the last header automatically.
const headerIdx = (wanted) => srcHeader.findIndex(h => String(h || '').trim().toLowerCase() === wanted.toLowerCase());
let nextFree = srcHeader.length;
const headersToAdd = [];
const outCol = (wanted) => {
  let i = headerIdx(wanted);
  if (i < 0) { i = nextFree++; headersToAdd.push({ index: i, name: wanted }); }
  return i;
};
const str = (v) => String(v ?? '').trim();
const addrsOf = (v) => String(v || '').split(/[,;\s]+/).map(e => e.trim().toLowerCase()).filter(Boolean);

// ---- Emails Beta ----
const bk = {};
for (const [f, h] of Object.entries(BETA)) bk[f] = keyOf(betaItems[0] || {}, h, 'Emails Beta');
const betaByEmail = new Map();
const takenNames = new Set();
for (const row of betaItems) {
  const nm = str(row[bk.name]);
  if (nm) takenNames.add(nm.toLowerCase());
  for (const a of addrsOf(str(row[bk.email]))) if (!betaByEmail.has(a)) betaByEmail.set(a, { name: nm, batch: str(row[bk.batch]) });
}

// ---- list sheet ----
const sk = {};
for (const f of ['name', 'email', 'contact']) sk[f] = keyOf(srcItems[0], SRC[f], 'List sheet');
// check columns may not exist yet (added below): read them only when present
for (const f of ['check', 'boxes', 'linked']) sk[f] = Object.keys(srcItems[0]).find(x => x.trim().toLowerCase() === SRC[f].toLowerCase()) || null;
const col = { status: colLetter(outCol(SRC.status)), matched: colLetter(outCol(SRC.matched)), check: colLetter(outCol(SRC.check)), boxes: colLetter(outCol(SRC.boxes)), linked: colLetter(outCol(SRC.linked)) };
const lastRow = Math.max(...srcItems.map(r => Number(r.row_number) || 0));
if (!(lastRow >= 2)) throw new Error('List sheet rows have no row_number');
const n = lastRow - 1;
const out = Array.from({ length: n }, () => ({ status: '', matched: '' }));
const stats = { existing: 0, existingWithNewAddress: 0, newContacts: 0, noEmail: 0, duplicateInList: 0 };
const existingWithNewAddress = [];
const seen = new Map(); const dups = [];
const contacts = [];

for (const row of srcItems) {
  const r = Number(row.row_number) - 2;
  const addrs = addrsOf(str(row[sk.email]));
  if (addrs.length === 0) { out[r].status = 'No email'; stats.noEmail++; continue; }
  if (addrs.every(a => seen.has(a))) { out[r].status = 'Duplicate in list'; dups.push({ r, of: seen.get(addrs[0]) }); stats.duplicateInList++; continue; }
  addrs.forEach(a => { if (!seen.has(a)) seen.set(a, r); });
  const hit = addrs.map(a => betaByEmail.get(a)).filter(Boolean);
  if (hit.length) {
    const first = hit[0];
    const missing = addrs.filter(a => !betaByEmail.has(a));
    out[r].matched = first.name;
    out[r].status = first.batch ? `New (${first.batch})` : 'Existing';
    if (missing.length) { out[r].status += ` (+${missing.length} address not in Emails Beta)`; stats.existingWithNewAddress++; existingWithNewAddress.push({ row: r + 2, client: first.name, addresses: missing }); }
    stats.existing++;
    continue;
  }
  const check = sk.check ? str(row[sk.check]) : '';
  const boxes = sk.boxes ? str(row[sk.boxes]) : '';
  contacts.push({
    r, row: r + 2, account: str(row[sk.name]), addrs, contactName: str(row[sk.contact]),
    check, checked: /^(found|not found)$/i.test(check), found: /^found$/i.test(check),
    types: [...new Set((boxes.match(/outlook|gmail/gi) || []).map(t => t.toLowerCase()))],
    boxes, linked: sk.linked ? addrsOf(str(row[sk.linked])).filter(a => !isOwn(a)) : []   // own addresses saved by an earlier run are ignored
  });
  stats.newContacts++;
}

const addrToContact = new Map();
contacts.forEach((c, i) => c.addrs.forEach(a => addrToContact.set(a, i)));

// ---- evidence grouping (union-find over contacts the check saw together) ----
const parent = contacts.map((_, i) => i);
const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
const union = (a, b) => { const ra = find(a), rb = find(b); if (ra !== rb) parent[Math.max(ra, rb)] = Math.min(ra, rb); };
const existingLink = new Map();   // contact index -> Set of existing client names
// An address that shows up in the linked lists of many different contacts is almost certainly
// one of our own mailboxes or a mass sender, not a person who belongs to a client. Using it
// would chain unrelated clients into one group, so it is ignored for grouping and reported.
const hubThreshold = Math.max(3, Number(cfg.hubThreshold) || 4);
const linkCount = new Map();
contacts.forEach(c => new Set(c.linked).forEach(a => linkCount.set(a, (linkCount.get(a) || 0) + 1)));
const hubs = new Set([...linkCount].filter(([, k]) => k >= hubThreshold).map(([a]) => a));
contacts.forEach((c, i) => {
  for (const a of c.linked) {
    if (hubs.has(a)) continue;
    if (addrToContact.has(a)) union(i, addrToContact.get(a));
    else if (betaByEmail.has(a)) { if (!existingLink.has(i)) existingLink.set(i, new Set()); existingLink.get(i).add(betaByEmail.get(a).name); }
  }
});
const groupsMap = new Map();
contacts.forEach((c, i) => { const root = find(i); if (!groupsMap.has(root)) groupsMap.set(root, []); groupsMap.get(root).push(i); });
const groups = [...groupsMap.values()].map(ix => ix.sort((a, b) => a - b));

const uniqueName = (base, firstAddr) => {
  let name = base || firstAddr.split('@')[0];
  if (!takenNames.has(name.toLowerCase())) { takenNames.add(name.toLowerCase()); return name; }
  const local = firstAddr.split('@')[0];
  let cand = `${name} (${local})`, k = 2;
  while (takenNames.has(cand.toLowerCase())) cand = `${name} (${local}) ${k++}`;
  takenNames.add(cand.toLowerCase());
  return cand;
};
const platformValue = (allAddrs, group) => {
  const union = [...new Set(group.flatMap(i => contacts[i].types))];
  if (union.length === 0) return '';
  const per = allAddrs.map(a => { const t = contacts[addrToContact.get(a)].types; const use = t.length ? t : union; return use.length === 1 ? use[0] : use; });
  return per.length === 1 && typeof per[0] === 'string' ? per[0] : JSON.stringify(per);
};

const appendRows = [];
const pendingGroups = [];
const nameClashes = [];
const sameAccountNote = [];
const bigGroups = [];
const noConversation = [];
const toCheck = [];
const newStatus = (c, i) => {
  let s = !c.checked ? 'New (not checked yet)' : (c.found ? 'New (conversation found)' : `New (${noConvFlag})`);
  if (existingLink.has(i)) s += `; linked to existing client ${[...existingLink.get(i)].join(' / ')}`;
  return s;
};
contacts.forEach((c, i) => { out[c.r].status = newStatus(c, i); });

for (const c of contacts) { if (!c.checked && toCheck.length < batchSize) toCheck.push({ row: c.row, addrs: c.addrs }); }
for (const g of groups) {
  if (!g.every(i => contacts[i].checked)) { pendingGroups.push(g.map(i => contacts[i].row)); continue; }
  if (g.length > 6) bigGroups.push({ rows: g.map(i => contacts[i].row), size: g.length });
  const first = contacts[g[0]];
  const base = first.account || first.contactName || '';
  const name = uniqueName(base, first.addrs[0]);
  if (name.toLowerCase() !== (base || first.addrs[0].split('@')[0]).toLowerCase()) nameClashes.push({ row: first.row, original: base, assigned: name });
  const allAddrs = [...new Set(g.flatMap(i => contacts[i].addrs))];
  const found = g.some(i => contacts[i].found);
  const mk = (nm, email, platform, label) => ({ [bk.name]: nm, [bk.email]: email, [bk.processed]: 'FALSE', [bk.platform]: platform, [bk.synced]: '', [bk.batch]: label });
  const label = found ? batch : `${batch} - ${noConvFlag}`;
  appendRows.push(mk(name, allAddrs.join(', '), found ? platformValue(allAddrs, g) : '', label));
  if (!found) noConversation.push({ name, rows: g.map(i => contacts[i].row) });
  g.forEach(i => {
    const c = contacts[i];
    out[c.r].matched = name;
    // (no name-only rows for the other contacts: who belongs to a group is in the list sheet's Matched client column)
  });
  g.forEach(i => { if (existingLink.has(i)) sameAccountNote.push({ row: contacts[i].row, newClient: name, linkedToExisting: [...existingLink.get(i)] }); });
}
// With the switch on, every group whose members are all checked is added in this run.
const addOn = cfg.addToEmailsBeta === true || String(cfg.addToEmailsBeta).toLowerCase() === 'true';
const rowsToAdd = addOn ? appendRows : [];
for (const d of dups) out[d.r].matched = out[d.of].matched;

const q = (t) => `'${String(t).replace(/'/g, "''")}'`;
const srcTab = String(cfg.sourceTab);
const sid = encodeURIComponent(cfg.sourceSheetId);
const sourceUpdate = {
  url: `https://sheets.googleapis.com/v4/spreadsheets/${sid}/values:batchUpdate`,
  body: { valueInputOption: 'RAW', data: [
    ...headersToAdd.map(h => ({ range: `${q(srcTab)}!${colLetter(h.index)}1`, values: [[h.name]] })),
    { range: `${q(srcTab)}!${col.status}2:${col.status}${n + 1}`, values: out.map(o => [o.status]) },
    { range: `${q(srcTab)}!${col.matched}2:${col.matched}${n + 1}`, values: out.map(o => [o.matched]) }
  ] }
};

return [{ json: {
  addToEmailsBeta: addOn, rowsToAdd,
  summary: {
    listRows: srcItems.length, ...stats,
    checked: contacts.filter(c => c.checked).length,
    conversationFound: contacts.filter(c => c.found).length,
    notChecked: contacts.filter(c => !c.checked).length,
    nextBatch: toCheck.length,
    groupsReady: groups.length - pendingGroups.length,
    groupsPending: pendingGroups.length,
    rowsToAppendToEmailsBeta: appendRows.length,
    noConversationClients: noConversation.length,
    nameClashesRenamed: nameClashes.length,
    largeGroups: bigGroups.length,
    hubAddressesIgnored: hubs.size
  },
  headersAdded: headersToAdd.map(h => h.name),
  toCheck, columns: col, srcTab, sourceSheetId: cfg.sourceSheetId,
  hubAddressesIgnored: [...hubs],
  nameClashes, linkedToExisting: sameAccountNote, bigGroups, noConversation, existingWithNewAddress,
  preview: appendRows.slice(0, 30).map(r => ({ Name: r[bk.name], Email: r[bk.email], Platform: r[bk.platform], Batch: r[bk.batch] })),
  sourceUpdate, appendRows
} }];
